@contextlib.contextmanager
def temp_root():
    """把「库根」临时指向一个合成目录，**只在本进程内**改模块级变量。

    为什么要它：selftest 必须走真实的扫描/写盘路径（否则测的是另一个函数），
    但**绝对不能在真库上写**。做法是让 ROOT 在 selftest 期间整体指向 tempfile
    合成库——路径一字不改地跑，落点全在临时目录里。退出时无论成败都恢复。
    """
    old_root, old_cwd, old_env = ROOT, os.getcwd(), os.environ.get(QC_DIR_ENV)
    tmp = K.make_temp_dir(prefix="qc_link_wrap_selftest_")
    try:
        globals()["ROOT"] = tmp
        os.chdir(tmp)
        os.environ[QC_DIR_ENV] = os.path.join(tmp, ".qc")   # 清单也只落合成库
        yield tmp
    finally:
        os.chdir(old_cwd)
        globals()["ROOT"] = old_root
        if old_env is None:
            os.environ.pop(QC_DIR_ENV, None)
        else:
            os.environ[QC_DIR_ENV] = old_env
        shutil.rmtree(tmp, ignore_errors=True)


# ---------------------------------------------------------------- 代码区掩码
#
# 🔴 为什么需要"掩码"而不是 `strip_code(t)` 了事：
#    本文件要在原文上**按位置改字符**（剥掉反引号），而 `strip_code` 只返回
#    "剔除后的文本"、丢掉了位置 ⇒ 直接拿它写回会把整页其它内容一起删掉。
#
# 🔴 更不能直接把 `strip_code` 的匹配范围拿来当"代码区"：
#    它的行内代码模式是 `` `[^`\n]*` ``，而**本工具要剥离的目标
#    `` `[[X]]` `` 恰好完美命中那个模式** —— 照搬的结果是 `mask` 把每一个
#    待剥离的目标自己标成"代码"⇒ 改动 0 处：闸门装上了，功能也一起关掉了
#    （本库第 4 号自检事故的同型：为了兼容变体把主干匹配搞没了）。
#    ⇒ 掩码规则必须**对目标特异**：
#        · 围栏块（``` / ~~~ 成对）整体为代码；
#        · 行内代码只在**反引号长度 ≥ 3** 时才算——因为作为"示例"的行内代码
#          必须能容纳目标本身（目标自带一对单反引号），撑不满 3 个反引号的
#          "行内代码"在语法上不可能是"包住目标的示例"；
#        · 任何一行里出现 ≥3 个连续反引号 ⇒ 该行按代码处理（宁可不改）。

_FENCE_RE = re.compile(r"```.*?```|~~~.*?~~~", re.S)      # 与 kb_lib.strip_code 同一围栏模式
_LINE_EXAMPLE_RE = re.compile(r"^[^\n]*`{3,}[^\n]*$", re.M)   # 含 ≥3 连续反引号的整行


def code_mask(t):
    """与 `t` 等长的掩码：True 表示该字符在**真实正文**里（不在"示例代码"中）。

    判据（对目标特异，见上方注释）：
      ① 成对围栏块 ```…``` / ~~~…~~~  整体为代码
      ② 含 ≥3 个**连续**反引号的整行（行内示例）整体为代码
      ③ 自证：`kb_lib.strip_code` 认为"没有代码"的文本，掩码必须全 True

    ⚠️ 有意**不**把单反引号对（`` `x` ``）当成代码：那会连带把本工具的目标
    `` `[[X]]` `` 一起保护起来，等于工具什么都不做（见上方注释）。
    """
    mask = [True] * len(t)
    for rx in (_FENCE_RE, _LINE_EXAMPLE_RE):
        for m in rx.finditer(t):
            for j in range(m.start(), min(m.end(), len(t))):
                mask[j] = False
    # ⚠️ 诚实边界：**不能**在这里加"若 `strip_code(t) != t` 却一个都没遮住 ⇒ 全屏蔽"的
    #    自证闸门。实测该闸门会把每一个正常目标都拦下：`strip_code` 的行内规则
    #    `` `[^`\n]*` `` 把 `` `[[X]]` `` 本身判成代码 ⇒ 掩码全 True
    #    ⇒ 闸门触发 ⇒ 全 False ⇒ 改动恒为 0 处。
    #    **闸门装上了，功能也一起关掉了**（本库第 4 号自检事故：为兼容变体把主干搞没）。
    #    ⇒ 这里不做"文字自证"，改用 selftest 里的**具体夹具**证明围栏区确实不被改写。
    return mask


def strip_backticks_outside_code(t):
    """剥掉**真实正文**中 `` `[[X]]` `` 的反引号；示例代码里的原样保留。

    返回 (新文本, 改动处数)。逐匹配按位置判定，与"先掩码再替换"等价。
    """
    mask = code_mask(t)
    n = [0]

    def _sub(m):
        if m.start() < len(mask) and mask[m.start()]:
            n[0] += 1
            return m.group(0)[1:-1]
        return m.group(0)             # 示例代码：不动

    return PAT.sub(_sub, t), n[0]


def sweep():
    """扫描被反引号包裹的 wikilink。**只统计真实正文**。

    🔴 2026-10-10：改用 `strip_backticks_outside_code` 同源的 `code_mask` 剔除
    围栏代码块与行内代码。原因：lint/QC 报告里专门用 `` `[[X]]` `` 演示
    "坏写法长什么样"，若把示例也算进来并交给 `--apply` 剥离，
    等于**篡改报告正文**（同类事故：`qc_fix_image_syntax` 报 34 处"图片语法错误"、
    真值 0，改写会破坏排版）。剔除后，"报多少就改多少"，count 与动作一致。
    """
    rows, total = [], 0
    for f in glob.glob("wiki/**/*.md", recursive=True):
        q = f.replace(os.sep, "/")
        if "/.index/" in q or ".claude-rename" in q:
            continue
        if os.path.basename(f)[:-3] in META:
            continue
        t = read_text(f)
        mask = code_mask(t)
        hits = [m.group(0) for m in PAT.finditer(t)
                if m.start() < len(mask) and mask[m.start()]]
        if hits:
            rows.append({"page": os.path.relpath(f, "wiki").replace(os.sep, "/"),
                         "n": len(hits), "sample": hits[0][:60]})
            total += len(hits)
    rows.sort(key=lambda r: -r["n"])
    return rows, total


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）+ 代码区剔除/写盘隔离夹具。"""
    ok = True

    # 🔴 守卫：进入时对真实落点拍快照，退出前比对——证明自检没碰真实库
    guard = _guard_state(wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),))

    # 正例：被反引号包裹的 wikilink 必须命中
    got = len(PAT.findall("见 `[[concepts/固态电解质]]` 一节"))
    print(f"  [{'ok' if got == 1 else 'FAIL'}] 正例 反引号包裹的 wikilink -> {got}")
    ok = ok and got == 1
    # 反例：未包裹的裸 wikilink **不得**命中（这是合法写法）
    got = len(PAT.findall("见 [[concepts/固态电解质]] 一节"))
    print(f"  [{'ok' if got == 0 else 'FAIL'}] 反例 裸 wikilink 不命中 -> {got}")
    ok = ok and got == 0
    # 🔴 反例（2026-10-10 起的新不变量）：**代码区里的示例不得被改写**。
    #    旧行为是"会命中、apply 前须人工确认"——把风险交给人的记忆，实测不可靠。
    #    这里刻意只用 fenced-only 样本：正文那一半另有正例（否则"一处都不改"
    #    也能让本夹具变绿，等于把功能删掉换一个绿的自检）。
    fenced = "```\n`[[concepts/Y]]`\n```\n"
    got, n = strip_backticks_outside_code(fenced)
    c_demo = (n == 0 and got == fenced)
    print(f"  [{'ok' if c_demo else 'FAIL'}] 🔴 反例 围栏代码区示例不被剥离"
          f"（改动 {n} 处）")
    ok = ok and c_demo
    # 🔴 反例：行内示例（反引号 ≥3 包裹目标）同样不得被改写
    inline = "示例：``` `[[concepts/Y]]` ```\n"
    got, n = strip_backticks_outside_code(inline)
    c_inline = (n == 0 and got == inline)
    print(f"  [{'ok' if c_inline else 'FAIL'}] 🔴 反例 行内示例（≥3 反引号）不被剥离"
          f"（改动 {n} 处）")
    ok = ok and c_inline
    # 正例：同一份文本里，正文目标被剥离、fenced 示例原样保留
    mixed = "正文 `[[concepts/X]]` 坏写法\n```\n示例 `[[concepts/Y]]`\n```\n"
    got, n = strip_backticks_outside_code(mixed)
    c_mixed = (n == 1 and "正文 [[concepts/X]] 坏写法" in got
               and "示例 `[[concepts/Y]]`" in got)
    print(f"  [{'ok' if c_mixed else 'FAIL'}] 正例 正文剥离 / fenced 保留 同时成立"
          f"（改动 {n} 处）")
    ok = ok and c_mixed
    # 正例：正文里的反引号包裹 wikilink 必须被剥离
    got, n = strip_backticks_outside_code("见 `[[concepts/X]]` 一节\n")
    c_prose = (n == 1 and "`" not in got)
    print(f"  [{'ok' if c_prose else 'FAIL'}] 正例 正文中的被包裹链接被剥离 -> "
          f"{got.strip()!r}")
    ok = ok and c_prose
    # 🔴 夹具：**目标自己不得被掩码吞掉**（照搬 strip_code 行内模式时的翻车点：
    #    掩码全 False ⇒ 改动 0 处，闸门装上了、功能也一起关掉了）
    t_probe = "见 `[[concepts/X]]` 一节\n"
    m_probe = code_mask(t_probe)
    ok_target = (m_probe[PAT.search(t_probe).start()]
                 and len(m_probe) == len(t_probe))
    print(f"  [{'ok' if ok_target else 'FAIL'}] 🔴 夹具 目标不被自身反引号掩掉"
          f"（mask 长度 {len(m_probe)}）")
    ok = ok and ok_target
    # 正例：全库扫描跑通（空库 0 处是合法状态；命中能力由下方合成夹具钉住）
    rows, total = sweep()
    print(f"  [ok] 全库扫描（已剔代码区）跑通 -> {total} 处 / {len(rows)} 页")
    # 正例：清单落点在库根、未落归档（**不再 create**：自检不得创建目录）
    wd = os.environ.get(QC_DIR_ENV) or qc_work_dir()
    safe = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if safe else 'FAIL'}] 写盘目标在库根、未落归档 -> {wd}")
    ok = ok and safe

    # ---- 夹具（只对合成库，绝不碰真库）----
    try:
        with temp_root() as tmp:
            wd2 = os.path.join(tmp, "wiki", "concepts")
            os.makedirs(wd2, exist_ok=True)
            p1 = os.path.join(wd2, "A-真引用.md")
            with open(p1, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ntype: concept\n---\n\n# 页\n见 `[[concepts/X]]` 一节\n")
            p2 = os.path.join(wd2, "B-示例.md")
            with open(p2, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ntype: concept\n---\n\n# 页\n```\n坏写法：`[[concepts/Y]]`\n"
                         "```\n")

            # 夹具 1（正例）：合成库里只报真引用那一页
            rows2, total2 = sweep()
            names = [r["page"] for r in rows2]
            c1 = (total2 == 1 and names == ["concepts/A-真引用.md"])
            print(f"  [{'ok' if c1 else 'FAIL'}] 夹具 正例 只报真引用页（代码里的示例不报）"
                  f" -> {total2} 处 {names}")
            ok = ok and c1

            # 🔴 夹具 2（frontmatter 不丢 + 代码区不碰）：走真实写盘路径
            saved = backup_files([os.path.join("wiki", r["page"]) for r in rows2])
            written = []
            for r in rows2:
                f = os.path.join("wiki", r["page"])
                t = read_text(f)
                new, n = strip_backticks_outside_code(t)
                if new != t:
                    write_keep_eol(f, new)
                    written.append(f)
            from kb_lib import split_frontmatter as _sf
            fm1, body1 = _sf(read_text(p1))
            fm2, body2 = _sf(read_text(p2))
            c2 = (len(written) == 1 and len(saved) == 1
                  and "`" not in body1 and "[[concepts/X]]" in body1
                  and "`[[concepts/Y]]`" in body2      # 代码里的示例原样保留
                  and fm1.strip() and fm2.strip())
            print(f"  [{'ok' if c2 else 'FAIL'}] 🔴 夹具 frontmatter 不丢 + 代码区不碰："
                  f"写后正文已剥、示例保留、frontmatter 可解析（备份 {len(saved)} / "
                  f"写 {len(written)}）")
            ok = ok and c2

            # 反例：写后复算必须抓出"写了但 frontmatter 读不出"的页
            p_broken = os.path.join(wd2, "C-写坏了.md")
            with open(p_broken, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ntype: concept\n---# 标题\n")
            caught = False
            sys.stdout.flush()          # 让下面 stderr 的告警落在夹具判定之后，输出不串行
            try:
                verify_written([p1, p_broken])
            except SystemExit as e:
                caught = (e.code or 0) != 0
            print(f"  [{'ok' if caught else 'FAIL'}] 反例 写后复算抓出 frontmatter 丢失"
                  f"（并置非零退出）")
            ok = ok and caught
    except Exception as e:                                        # noqa: BLE001
        print(f"  [FAIL] 夹具异常: {type(e).__name__}: {e}")
        ok = False

    # 🔴 守卫：自检未改动仓库内任何落点
    diff = _guard_diff(guard, _guard_state(
        wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),)))
    print(f"  [{'ok' if not diff else 'FAIL'}] 🔴 守卫：自检未改动仓库内任何落点"
          f"（{len(diff)} 处变化）")
    if diff:
        for d in diff[:10]:
            print("       ", d)
    ok = ok and not diff

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="反引号包裹的 wikilink 普查")
    ap.add_argument("--apply", action="store_true", help="就地剥离反引号")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    rows, total = sweep()
    print("被反引号包裹的 wikilink（已剔代码区）：%d 处，涉及 %d 页" % (total, len(rows)))
    for r in rows[:25]:
        print("   %3d  %-46s %s" % (r["n"], r["page"][:46], r["sample"]))

    if not a.apply:
        # 🔴 干跑**零写盘**：清单 json 原先无条件写到 `.qc/link_wrap.json`，
        #    那是"干跑有副作用"。清单内容已全部打在下面的 stdout 里，
        #    落盘只在 --apply 时做（apply 本就要动 wiki，多一份清单是操作留痕）。
        print("\nDRY-RUN：未写盘（清单 json 也只在 --apply 时落 .qc/）")
        if rows:
            print("加 --apply 就地剥离反引号（代码块/行内代码里的示例已自动排除）")
        return 0

    # —— 铁律 3：批量写盘前先备份、写后复算总量 ——
    targets = ["wiki/" + r["page"] for r in rows]
    saved = backup_files(targets)
    if targets and not saved:
        print("❌ 备份失败，拒绝写盘", file=sys.stderr)
        return 2
    print("备份 %d 个待改文件 -> %s" % (len(saved), backup_dir()))

    written = []
    for r in rows:
        f = "wiki/" + r["page"]
        t = read_text(f)
        # 逐匹配按位置判定：代码块/行内代码里的示例一律不动
        new, n = strip_backticks_outside_code(t)
        if new != t:
            write_keep_eol(f, new)          # 保原换行风格，避免整篇 diff
            written.append(f)

    out = os.path.join(qc_work_dir(create=True), "link_wrap.json")
    json.dump(rows, open(out, "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print("清单 -> %s" % out)
    print("\n已剥离 %d 页" % len(written))
    verify_written(written)
    return 0


if __name__ == "__main__":
    sys.exit(main())
